import{_ as i,a0 as u,w as s,s as a,ao as l,I as n,x as e,a1 as o,A as p}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const h=JSON.parse('{"title":"戴文的Linux内核专题：22 配置内核 (18) | LCTT x X-CMD","titleTemplate":false,"description":"戴文的Linux内核专题：22 配置内核 (18) | LCTT (The Linux Kernel) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"戴文的Linux内核专题：22 配置内核 (18) | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"戴文的Linux内核专题：22 配置内核 (18) | LCTT (The Linux Kernel) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"The Linux Kernel/22 The Linux Kernel--Configuring the Kernel Part 18","title":"戴文的Linux内核专题：22 配置内核 (18)","tag":"The Linux Kernel","desc":""},"relativePath":"The Linux Kernel/22 The Linux Kernel--Configuring the Kernel Part 18.md","filePath":"[post].md"}'),d={name:"The Linux Kernel/22 The Linux Kernel--Configuring the Kernel Part 18.md"};function q(I,t,x,m,C,M){const r=u("Link");return s(),a("div",null,[t[11]||(t[11]=l('<h1 id="戴文的linux内核专题-22-配置内核-18" tabindex="-1">戴文的Linux内核专题：22 配置内核 (18) <a class="header-anchor" href="#戴文的linux内核专题-22-配置内核-18" aria-label="Permalink to “戴文的Linux内核专题：22 配置内核 (18)”">​</a></h1><p><img src="http://www.linux.org/attachments/slide-jpg.616/" alt=""></p><p>你好！准备好阅读下一篇文章了么？在本篇中，我们将会讨论辅助显示。辅助显示是一些小的LCD屏幕；大多数小于或等于128x64。接着，我们会讨论用户空间IO驱动，一些虚拟驱动，Hyper-V，开发中驱动，IOMMU，和其他一些内核特性。</p><p>第一个配置辅助显示的驱动是&quot;KS0108 LCD Controller&quot;。KS0108 LCD Controller是由三星制造的图形控制器。</p><p>下面可以设置LCD并口地址(Parallel port where the LCD is connected)。第一个并口地址是0x378，下一个是0x278，第三个是0x3BC。这些不是地址唯一的选择。大多数人不需要改变这个。shell命令&quot;cat /proc/ioports&quot;会列出可用的并口和地址。</p><p>内核可以设置KS0108 LCD 控制器的写入延时到并口(Delay between each control writing (microseconds))。默认的值大部分是正确的，因此一般不需要更改。</p><p>&quot;CFAG12864B LCD&quot;屏幕是一块128x64，双色LCD屏幕。这块屏幕依赖于KS0108 LCD控制器。</p><p>可以改变这些LCD屏幕的刷新率(Refresh rate (hertz))。通常上，更高的刷新率会导致更多的CPU活动。这意味着一个缓慢的系统需要一个更低的刷新率。</p><p>设置完辅助显示后，接着设置&quot;Userspace I/O drivers&quot;。用户空间系统允许用户的应用和进程访问内核中断和内存地址。启用了它，一些驱动可以放在用户空间。</p><p>&quot;generic Hilscher CIF Card driver&quot;用于Profibus卡和Hilscher CIF卡。</p><p>&quot;Userspace I/O platform driver&quot;在用户空间创建通用驱动系统。</p><p>下一个驱动和上面的相同，但是增加IRQ处理(Userspace I/O platform driver with generic IRQ handling)。</p><p>下面的驱动又像前面的一个，但是增加了动态内存支持(Userspace platform driver with generic irq and dynamic memory)。</p><p>下面，是一些供应商/设备特性的驱动。</p><p>接着是一些通用PCI/PCIe卡驱动(Generic driver for PCI 2.3 and PCI Express cards)。</p><p>下面的驱动用于&quot;VFIO support for PCI devices&quot;。VFIO代表Virtual Function Input/Output(虚拟功能输入/输出)。VFIO允许设备直接以安全方式访问用户空间。</p><p>&quot;VFIO PCI support for VGA devices&quot;允许VGA通过VFIO被PCI支持。</p><p>接下来是virtio驱动。virtio是一个IO虚拟化平台。这个虚拟软件用于操作系统虚拟化。这在Linux系统上的虚拟机上运行一个操作系统时需要。</p><p>我们第一个可以配置的virtio驱动是&quot;PCI driver for virtio devices&quot;。这允许虚拟访问PCI</p><p>&quot;Virtio balloon driver&quot;允许虚拟系统的内存根据需要扩展或减少。通常上，没有人希望在需要内存的时候，虚拟系统保留它可能不会使用的内存。</p><p>下面的驱动允许内存映射到virtio设备(Platform bus driver for memory mapped virtio devices)。</p><p>如果Linux内核需要运行在微软的Hyper-V系统上，那么启用这个驱动(Microsoft Hyper-V client drivers)。这允许Linux能够成为Hyper的访客/客户端系统。</p><p><img src="http://www.linux.org/attachments/kernel_18-png.617/" alt=""></p><p>下面，我们会配置处于开发阶段的驱动。这些驱动正在开发当中，可能会变化很快，或者还没到Linux内核的质量标准。这个分类中的驱动只有Android驱动(在内核3.9.4中)。是的，Andorid使用Linux内核，这使得Andorid变成了一个Linux系统。然而，这仍然有争议。如果内核是用于Android，那么最好启用所有的驱动。</p><p>&quot;Android Binder IPC Driver&quot;提供了对于Binder的支持，它允许Andorid系统进程间相互通信。</p><p>下面可以启用ashmen驱动(Enable the Anonymous Shared Memory Subsystem)。Ashmem代表&quot;Anonymous SHared MEMory&quot;(虚拟内存共享)或者&quot;Android SHared MEMory&quot;(Andorid共享内存)。</p><p>&quot;Android log driver&quot;提供了完整的Andorid日志系统。</p><p>&quot;Timed output class driver&quot; 和 &quot;Android timed gpio driver&quot;允许Andorid系统操作GIP引脚并在超时后取消操作。</p><p>&quot;Android Low Memory Killer&quot;会在需要更多内存关闭进程。这个特性会杀死不再使用或活跃的任务。</p><p>&quot;Android alarm driver&quot;使内核在设定的间隔后唤醒。</p><p>在配置完开发阶段的驱动后，下面的驱动用于X86平台。这些驱动是 X86 (32-bit)的供应商/设备特定硬件。</p><p>下一个驱动是&quot;Mailbox Hardware Support&quot;。这个框架控制邮箱队列和硬件邮箱系统的中断信号。</p><p>&quot;IOMMU Hardware Support&quot;链接内存到能够使用DMA的设备上。IOMMU增强了DMA。IOMMU映射地址并阻止故障设备访问内存。IOMMU同样允许硬件访问比没有IOMMU更多内存。</p><p>&quot;AMD IOMMU support&quot;提供了对AMD设备更好的IOMMU支持。</p><p>对于AMD IOMMU支持存在调试特性(Export AMD IOMMU statistics to debugfs)。</p><p>存在一个对于AMD硬件的更新版本的IOMMU驱动(AMD IOMMU Version 2 driver)。</p><p>Linux内核同样支持对Intel设备的IOMMU驱动支持(Support for Intel IOMMU using DMA Remapping Devices)。</p><p>一些设备可能会接受不同的电压和时钟频率。这个驱动允许操作系统控制设备的电压输出和时钟频率(Generic Dynamic Voltage and Frequency Scaling (DVFS) support)。启用了这个驱动，可以启用下面的那些对于电源/性能管理特性。</p><p>&quot;Simple Ondemand&quot;就像上面的，但是只会基于设备活动改变时钟频率。通常上，更多的活动意味着设备需要更快的时钟速率来使用更多的资源需求。</p><p>&quot;Performance&quot;允许系统设置最高支持的时钟速度以满足最好的性能。这会增加电源消耗。</p><p>&quot;Powersave&quot;会设置时钟频率到最低以节约电源。</p><p>&quot;Userspace&quot;允许用户空间设置时钟频率。</p><p>&quot;External Connector Class (extcon) support&quot;使得用户空间可以监视外部连接器如USB和AC口。这允许应用了解是否插入了线缆。用户几乎都希望启用这个。如果任何人由于某个合理的理由禁用了它，请告诉我们为什么这么做。</p><p>&quot;GPIO extcon support&quot;驱动就像上面的驱动，但是它只对于GPIO管脚。</p><p>接下来是不同的供货商/设备特定的内存控制器(Memory Controller drivers)。内存芯片控制器可能是独立的设备或者内置在内存芯片上。这些控制器管理这输入和输出的数据流。</p><p>&quot;Industrial I/O support&quot;驱动提供了标准的传感器接口而不管总线的类型(像PCIe、spi、GPIO等等)。IIO是&quot;Industrial I/O support&quot;(工业IO)的通用缩写。</p><p>Linux内核提供了大量不同的加速器、放大器模数转换器、惯性测量单元、光敏传感器、磁场传感器和其他许多传感器和转换器的支持。</p><p>&quot;Intel Non-Transparent Bridge support&quot;驱动支持连接到系统的PCIe硬件桥。所有到映射内存的写入会镜像到两个系统中。</p><p>&quot;VME bridge support&quot;和上面的相同除了桥使用的是VME，这是一个不同的总线标准。</p><p>&quot;Pulse-Width Modulation (PWM) Support&quot;通过调节从这些设备收到的平均功率调节背光灯和风扇速度。</p><p>&quot;IndustryPack bus support&quot;提供了对IndustryPack总线标准的支持。</p><p>下一篇文章，我们会继续配置固件驱动。谢谢!</p><hr>',53)),n("p",null,[t[1]||(t[1]=e("via: ",-1)),o(r,{href:"http://www.linux.org/threads/the-linux-kernel-configuring-the-kernel-part-18.4896/"},{default:p(()=>[...t[0]||(t[0]=[e("http://www.linux.org/threads/the-linux-kernel-configuring-the-kernel-part-18.4896/",-1)])]),_:1})]),n("p",null,[t[4]||(t[4]=e("译者：",-1)),o(r,{href:"https://github.com/geekpi"},{default:p(()=>[...t[2]||(t[2]=[e("geekpi",-1)])]),_:1}),t[5]||(t[5]=e(" 校对：",-1)),o(r,{href:"https://github.com/wxy"},{default:p(()=>[...t[3]||(t[3]=[e("wxy",-1)])]),_:1})]),n("p",null,[t[8]||(t[8]=e("本文由 ",-1)),o(r,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...t[6]||(t[6]=[e("LCTT",-1)])]),_:1}),t[9]||(t[9]=e(" 原创翻译，",-1)),o(r,{href:"http://linux.cn/"},{default:p(()=>[...t[7]||(t[7]=[e("Linux中国",-1)])]),_:1}),t[10]||(t[10]=e(" 荣誉推出",-1))])])}const f=i(d,[["render",q]]);export{h as __pageData,f as default};
